function [y] = speed_limited(t, om, speed_max)
%SPEED_LIMITED  The motor torque t at speed om, none that speeds the wheel past speed_max.
%   t: real[1] (passed a plain number)
%   om: real[1] (passed a plain number)
%   speed_max: real[1] (passed a plain number)
%   returns y: real[1] (passed a plain number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    y = 0;
    y = asils.pc.choose(((asils.pc.fabs(om) >= speed_max) && (sign(t) == sign(om))), 0, t);
end
